#[rustfmt::skip]
impl ScalarOp {
    /// The verb whose parameters these are.
    pub const fn verb(&self) -> Verb {
        match self {
            Self::Greatest => Verb::Greatest,
            Self::Least => Verb::Least,
            Self::Mapping { .. } => Verb::Mapping,
            Self::Cut { .. } => Verb::Cut,
            Self::StrPad { .. } => Verb::StrPad,
            Self::StrSubstr { .. } => Verb::StrSubstr,
            Self::StrLength => Verb::StrLength,
            Self::StrExtract { .. } => Verb::StrExtract,
            Self::StrReplace { .. } => Verb::StrReplace,
            Self::StrTemplate { .. } => Verb::StrTemplate,
            Self::StrCase { .. } => Verb::StrCase,
            Self::RoundHalfAwayFromZero { .. } => Verb::RoundHalfAwayFromZero,
            Self::StrDecimal { .. } => Verb::StrDecimal,
            Self::Diff { .. } => Verb::Diff,
            Self::Impute { .. } => Verb::Impute,
            Self::Precision { .. } => Verb::Precision,
            Self::ImputationFlag { .. } => Verb::ImputationFlag,
            Self::ToDate => Verb::ToDate,
            Self::DateText { .. } => Verb::DateText,
            Self::StudyDay => Verb::StudyDay,
            Self::ToEpochDay => Verb::ToEpochDay,
            Self::Dtc => Verb::Dtc,
            Self::TimeOfDay => Verb::TimeOfDay,
            Self::Shift { .. } => Verb::Shift,
            Self::DurationValue { .. } => Verb::DurationValue,
            Self::DurationText { .. } => Verb::DurationText,
        }
    }
    /// The parameters `verb` writes, as its declaration types them, or
    /// `None` when one it requires is omitted or one holds a value its type
    /// cannot read; the operation built from them validates the rest.
    pub(crate) fn read(verb: Verb, written: &mut dyn Written) -> Option<Self> {
        Some(match verb {
            Verb::Greatest => Self::Greatest,
            Verb::Least => Self::Least,
            Verb::Mapping => Self::Mapping {
                dict: written.dictionary("dict")??,
                case_sensitive: written.boolean("case_sensitive")?.unwrap_or(true),
            },
            Verb::Cut => Self::Cut {
                breaks: written.numbers("breaks")??,
                labels: written.texts("labels")??,
                closed: match written.text("closed")? { Some(text) => Closed::from_name(&text)?, None => Closed::Left },
            },
            Verb::StrPad => Self::StrPad {
                width: written.int("width")??,
            },
            Verb::StrSubstr => Self::StrSubstr {
                start: written.int("start")?,
                length: written.int("length")?,
                piece: written.int("piece")?,
            },
            Verb::StrLength => Self::StrLength,
            Verb::StrExtract => Self::StrExtract {
                pattern: written.text("pattern")??,
                group: written.int("group")?.unwrap_or_else(|| "0".into()),
            },
            Verb::StrReplace => Self::StrReplace {
                pattern: written.text("pattern")??,
                replacement: written.text("replacement")??,
            },
            Verb::StrTemplate => Self::StrTemplate {
                template: written.text("template")??,
            },
            Verb::StrCase => Self::StrCase {
                to: TextCase::from_name(&written.text("to")??)?,
                delimiters: written.text("delimiters")?,
            },
            Verb::RoundHalfAwayFromZero => Self::RoundHalfAwayFromZero {
                digits: written.int("digits")??,
            },
            Verb::StrDecimal => Self::StrDecimal {
                decimals: written.int("decimals")??,
                width: written.int("width")?,
            },
            Verb::Diff => Self::Diff {
                kind: TemporalType::from_name(&written.text("type")??)?,
                unit: TimeUnit::from_name(&written.text("unit")??)?,
                closed: match written.text("closed")? { Some(text) => Closed::from_name(&text)?, None => Closed::Right },
            },
            Verb::Impute => Self::Impute {
                kind: TemporalType::from_name(&written.text("type")??)?,
                month: written.int("month")?,
                day: match written.int("day") { Some(value) => value.map(ImputeDay::Int), None => Some(ImputeDay::DayRule(DayRule::from_name(&written.text("day")??)?)) },
                time: match written.text("time")? { Some(text) => Some(TimeRule::from_name(&text)?), None => None },
            },
            Verb::Precision => Self::Precision {
                kind: TemporalType::from_name(&written.text("type")??)?,
            },
            Verb::ImputationFlag => Self::ImputationFlag {
                part: FlagPart::from_name(&written.text("part")??)?,
                seconds_collected: written.boolean("seconds_collected")?.unwrap_or(true),
            },
            Verb::ToDate => Self::ToDate,
            Verb::DateText => Self::DateText {
                forms: written.texts("forms")??.iter().map(|text| DateForm::from_name(text)).collect::<Option<_>>()?,
            },
            Verb::StudyDay => Self::StudyDay,
            Verb::ToEpochDay => Self::ToEpochDay,
            Verb::Dtc => Self::Dtc,
            Verb::TimeOfDay => Self::TimeOfDay,
            Verb::Shift => Self::Shift {
                kind: TemporalType::from_name(&written.text("type")??)?,
                unit: match written.text("unit")? { Some(text) => Some(TimeUnit::from_name(&text)?), None => None },
            },
            Verb::DurationValue => Self::DurationValue {
                unit: TimeUnit::from_name(&written.text("unit")??)?,
            },
            Verb::DurationText => Self::DurationText {
                unit: TimeUnit::from_name(&written.text("unit")??)?,
            },
            _ => return None,
        })
    }
}

